[
    {
        "role": "bullet",
        "segment": "Size measure 1: number of objects and methods (an OO size measure).",
        "citations": [
            {
                "type": "source_text",
                "content": "Pfleeger (1991) used objects and methods as a basic size measure in her effort-estimation approach; she found that her method was more accurate than COCOMO in predicting the resulting effort needed to build several OO systems.",
                "img_id": null
            },
            {
                "type": "source_text",
                "content": "the estimation technique can be reapplied during development, and the estimate inputs are directly comparable. In other words, it is easy to see what the initial size is, and to track its growth over the product's life.",
                "img_id": null
            }
        ],
        "type": null
    },
    {
        "role": "bullet",
        "segment": "Size measure 2: number of scenario scripts (NSS) in the use cases.",
        "citations": [
            {
                "type": "source_text",
                "content": "Lorenz and Kidd count the number of scenario scripts (NSS) in the use cases.",
                "img_id": null
            },
            {
                "type": "source_text",
                "content": "They report that this measure is correlated with application size and number of test cases.",
                "img_id": null
            },
            {
                "type": "source_text",
                "content": "As a size measure, it can feed an estimation model for predicting project effort or duration. As a test case estimate, it helps the test team prepare test cases and allocate resources for future testing activities.",
                "img_id": null
            }
        ],
        "type": null
    }
]

