[
    {
        "role": "bullet",
        "segment": "Developers don't translate clearly stated needs into a successful system.",
        "citations": [
            {
                "type": "source_text",
                "content": "Developers can't translate clearly stated needs into a successful system.",
                "img_id": null
            }
        ],
        "type": null
    },
    {
        "role": "bullet",
        "segment": "Developers set unrealistic standards for requirements definition.",
