[
  {
    "role": "paragraph",
    "segment": "Below is a simple C-style implementation of a stack of integers using a fixed-size array with a maximum capacity of 100 elements. It provides empty, full, push, pop, and top operations, and returns an error when push is attempted on a full stack or pop/top are attempted on an empty stack.",
    "citations": []
  },
  {
    "role": "paragraph",
    "segment": "#include <stdio.h>
#include <stdbool.h>

#define MAX_STACK 100

typedef struct {
    int data[MAX_STACK];
    int top; // index of the current top element, -1 means empty
} Stack;

// Initialize an empty stack
void initStack(Stack *s) {
    s->top = -1;
}

// Check if the stack is empty
bool isEmpty(const Stack *s) {
    return s->top == -1;
}

// Check if the stack is full
bool isFull(const Stack *s) {
    return s->top == MAX_STACK - 1;
}

// Push an element onto the stack; returns true on success, false if full
bool push(Stack *s, int value) {
    if (isFull(s)) {
        // stack is full, cannot push
        return false;
    }
    s->data[++(s->top)] = value;
    return true;
}

// Pop the top element; returns true on success and stores the popped value in out, false if empty
bool pop(Stack *s, int *out) {
    if (isEmpty(s)) {
        return false;
    }
    *out = s->data[(s->top)--];
    return true;
}

// Get the top element without removing; returns true on success and stores the value in out, false if empty
bool top(const Stack *s, int *out) {
    if (isEmpty(s)) {
        return false;
    }
    *out = s->data[s->top];
    return true;
}

// Example usage (optional, can be removed if not needed)
int main() {
    Stack s;
    initStack(&s);

    // push some values
    for (int i = 0; i < 5; ++i) {
        if (!push(&s, i)) {
            printf("Stack is full, cannot push %d\n", i);
        }
    }

    // show top
    int val;
    if (top(&s, &val)) {
        printf("Top: %d\n", val);
    } else {
        printf("Stack is empty\n");
    }

    // pop all
    while (pop(&s, &val)) {
        printf("Popped: %d\n", val);
    }

    if (!pop(&s, &val)) {
        printf("Stack is empty, cannot pop\n");
    }

    return 0;
}
",
    "type": null
  }
]

answer:
Below is a simple C-style implementation of a stack of integers using a fixed-size array with a maximum capacity of 100 elements. It provides empty, full, push, pop, and top operations, and returns an error when push is attempted on a full stack or pop/top are attempted on an empty stack.

#include <stdio.h>
#include <stdbool.h>

#define MAX_STACK 100

typedef struct {
    int data[MAX_STACK];
    int top; // index of the current top element, -1 means empty
} Stack;

// Initialize an empty stack
void initStack(Stack *s) {
    s->top = -1;
}

// Check if the stack is empty
bool isEmpty(const Stack *s) {
    return s->top == -1;
}

// Check if the stack is full
bool isFull(const Stack *s) {
    return s->top == MAX_STACK - 1;
}

// Push an element onto the stack; returns true on success, false if full
bool push(Stack *s, int value) {
    if (isFull(s)) {
        // stack is full, cannot push
        return false;
    }
    s->data[++(s->top)] = value;
    return true;
}

// Pop the top element; returns true on success and stores the popped value in out, false if empty
bool pop(Stack *s, int *out) {
    if (isEmpty(s)) {
        return false;
    }
    *out = s->data[(s->top)--];
    return true;
}

// Get the top element without removing; returns true on success and stores the value in out, false if empty
bool top(const Stack *s, int *out) {
    if (isEmpty(s)) {
        return false;
    }
    *out = s->data[s->top];
    return true;
}

// Example usage (optional, can be removed if not needed)
int main() {
    Stack s;
    initStack(&s);

    // push some values
    for (int i = 0; i < 5; ++i) {
        if (!push(&s, i)) {
            printf("Stack is full, cannot push %d\n", i);
        }
    }

    // show top
    int val;
    if (top(&s, &val)) {
        printf("Top: %d\n", val);
    } else {
        printf("Stack is empty\n");
    }

    // pop all
    while (pop(&s, &val)) {
        printf("Popped: %d\n", val);
    }

    if (!pop(&s, &val)) {
        printf("Stack is empty, cannot pop\n");
    }

    return 0;
}

